function add(string $type, string $title, ?string $timezoneName = null, string $votingVariant = Poll::VARIANT_SIMPLE): Poll {
		if (!$this->appSettings->getPollCreationAllowed()) {
			throw new ForbiddenException('Poll creation is disabled');
		}

		// Validate valuess
		if (!in_array($type, $this->getValidPollType())) {
			throw new InvalidPollTypeException('Invalid poll type');
		}

		if (!$title) {
			throw new EmptyTitleException('Title must not be empty');
		}

		$timestamp = time();
		$this->poll = new Poll();
		$this->poll->setType($type);
		$this->poll->setVotingVariant($votingVariant);
		$this->poll->setTitle($title);
		$this->poll->setCreated($timestamp);
		$this->poll->setLastInteraction($timestamp);
		$this->poll->setOwner($this->userSession->getCurrentUserId());
		$this->poll->setTimezoneName($timezoneName);

		// create new poll before resetting all values to
		// ensure that the poll has all required values and an id
		// later checks may fail if the poll has no id
		$this->poll = $this->pollMapper->insert($this->poll);

		$this->poll->setDescription('');
		$this->poll->setAccess(Poll::ACCESS_PRIVATE);
		$this->poll->setExpire(0);
		$this->poll->setAnonymousSafe(0);
		$this->poll->setAllowMaybe(0);
		$this->poll->setVoteLimit(0);
		$this->poll->setShowResults(Poll::SHOW_RESULTS_ALWAYS);
		$this->poll->setDeleted(0);
		$this->poll->setAdminAccess(0);

		$this->pollMapper->update($this->poll);

		$this->eventDispatcher->dispatchTyped(new PollCreatedEvent($this->poll));

		return $this->poll;
	}

methods.Service/OptionService.php::add:
function add(
		int $pollId,
		SimpleOption $simpleOption,
		bool $voteYes = false,
	): Option {
		$this->getPoll($pollId)->request(Poll::PERMISSION_OPTION_ADD);

		// Build the new option
		$newOption = new Option();
		$newOption->setPoll($this->poll->getId());
		// A new option initially is positioned at the end of the list
		$newOption->setOrder($this->getHighestOrder($pollId) + 1);
		$newOption->setFromSimpleOption($simpleOption, $this->poll->getType());

		if (!$this->poll->getIsPollOwner()) {
			$newOption->setOwner($this->userSession->getCurrentUserId());
		}
		try {
			// Insert the new option
			$newOption = $this->optionMapper->insert($newOption);
		} catch (Exception $e) {
			$this->logger->error('Error while adding option', [
				'optionText' => json_encode($newOption),
				'pollId' => $pollId,
				'exceptionMessage' => $e->getMessage(),
			]);
			// TODO: Change exception catch to actual exception
			// Currently OC\DB\Exceptions\DbalException is thrown instead of
			// UniqueConstraintViolationException
			// since the exception is from private namespace, we check the type string
			if (get_class($e) === 'OC\DB\Exceptions\DbalException' && $e->getReason() === Exception::REASON_UNIQUE_CONSTRAINT_VIOLATION) {

				// Option already exists, so we need to update the existing one
				// and remove deleted setting
				$option = $this->optionMapper->findByPollAndText($pollId, $newOption->getPollOptionHash(), true);
				$option->setDeleted(0);

				$newOption = $this->optionMapper->update($option);

			} else {
				throw $e;
			}
		}

		if ($voteYes) {
			// Set the vote for the new option on request
			$this->voteService->set($newOption, Vote::VOTE_YES);
		}

		$this->eventDispatcher->dispatchTyped(new OptionCreatedEvent($newOption));

		return $newOption;
	}

